// ===========================
// 制度の計算機 — 医療費控除の値の表（値・出典・確認日をセットで）
// 令和8年分（2026 年 1〜12 月に支払った医療費。令和9年＝2027 年の確定申告）。
// どの値も下の SOURCES の原文（e-Gov 法令検索・国税庁）を 2026-09-24 に読んで写した。
// 所得税の速算表の 1,805 万円までと、給与所得控除後の金額の表・基礎控除は lib/tax2026.js（年末調整と共用）を使う。
// ブラウザでは window.IryohiValues、Node（テスト）では module.exports で使う
// ===========================
(function (root) {
  'use strict';

  var CHECKED = '2026-09-24';   // 下の出典を最後に原文で確かめた日
  var NTA = 'https://www.nta.go.jp/';
  var TA = NTA + 'taxes/shiraberu/taxanswer/shotoku/';

  var SOURCES = [
    { key: 'law73', label: '所得税法 73条（医療費控除）', url: 'https://laws.e-gov.go.jp/law/340AC0000000033', where: '総所得金額・退職所得金額・山林所得金額の合計額の 5%（10万円を超えるときは 10万円）を超える部分、200万円まで。89条（税率 5%〜45%）、190条（年末調整で引く控除に 73条は入らない）' },
    { key: 'sochi', label: '租税特別措置法 41条の17（セルフメディケーション税制）', url: 'https://laws.e-gov.go.jp/law/332AC0000000026', where: '令和8年分まで: 平成29年〜令和8年に支払った特定一般用医薬品等購入費。1万2千円を超える部分、8万8千円まで。通常の医療費控除との選択' },
    { key: 'sochi2027', label: '租税特別措置法 41条の17（令和9年1月1日施行版。令和8年法律第12号による改正後）', url: 'https://laws.e-gov.go.jp/law/332AC0000000026/20270101_508AC0000000012', where: 'スイッチOTC医薬品は期限なし、それ以外は令和13年12月31日まで。1万2千円・8万8千円は変わらない。体外診断用医薬品を追加' },
    { key: 'fukko', label: '復興財源確保法 13条（平成23年法律第117号）', url: 'https://laws.e-gov.go.jp/law/423AC0000000117', where: '復興特別所得税 = 基準所得税額 × 2.1%（令和8年分）。令和9年分からは 1.1% ＋ 防衛特別所得税 1%（合計 2.1% は同じ）' },
    { key: 'chiho', label: '地方税法 34条1項2号・314条の2第1項2号（住民税の医療費控除）、附則4条の5（セルフメディケーション税制。令和9年度分まで）、35条・314条の3（所得割の標準税率 4%・6%）', url: 'https://laws.e-gov.go.jp/law/325AC0000000226', where: '所得税と同じ式（5%・10万円・200万円）。令和8年の支払い分は令和9年度の住民税で引く' },
    { key: 'chiho2027', label: '地方税法 附則4条の5（令和9年1月1日施行版。令和8年法律第2号による改正後）', url: 'https://laws.e-gov.go.jp/law/325AC0000000226/20270101_508AC0000000002', where: '住民税のセルフメディケーション税制を「平成30年度以後の各年度分」に（期限の撤廃）' },
    { key: 'ta1120', label: '国税庁 タックスアンサー No.1120 医療費を支払ったとき（医療費控除）［令和8年4月1日現在法令等］', url: TA + '1120.htm', where: '「医療費控除の金額は、次の式で計算した金額（最高で200万円）です。」／「（実際に支払った医療費の合計額-（1）の金額）-（2）の金額」／「（2）10万円 （注）その年の 総所得金額等 が200万円未満の人は、 総所得金額等 の5パーセントの金額」' },
    { key: 'ta1129', label: '国税庁 タックスアンサー No.1129・No.1131（セルフメディケーション税制・選択適用）［令和8年4月1日現在法令等］', url: TA + '1129.htm', where: '「実際に支払った特定一般用医薬品等購入費の合計額（保険金などで補填される部分を除きます。）から12,000円を差し引いた金額（最高88,000円）です。」' },
    { key: 'ta2260', label: '国税庁 タックスアンサー No.2260 所得税の税率［令和8年4月1日現在法令等］', url: TA + '2260.htm', where: '「課税される所得金額（1,000円未満の端数金額を切り捨てた後の金額です。）」／「40,000,000円 以上 45％ 4,796,000円」' },
    { key: 'ta2030', label: '国税庁 タックスアンサー No.2030 還付申告', url: TA + '2030.htm', where: '還付申告書は翌年1月1日から5年間提出できる' },
    { key: 'meisai', label: '国税庁「医療費控除の明細書」（様式の Excel 版）・「セルフメディケーション税制の明細書」', url: NTA + 'taxes/shiraberu/shinkoku/yoshiki/02/xlsx/ref1.xlsx', where: '控除額の計算欄: C = A − B（マイナスは 0）、E = D × 0.05（1円未満切り捨て）、F = E と 10万円の少ないほう、控除額 = C − F（最高200万円、赤字は 0）。セルフは C − 12,000円（最高 8万8千円）' },
    { key: 'kurashi', label: '国税庁「暮らしの税情報」（令和8年度版）医療費を支払ったとき', url: NTA + 'publication/pamph/koho/kurashi/html/04_1.htm', where: '通常の医療費控除を選ぶと、治療のための対象医薬品の購入費は医療費に含めて計算する。スイッチOTC以外は令和13年12月31日まで' },
    { key: 'rei', label: '国税庁「医療費控除を受ける方の記載例」（令和2年分）', url: NTA + 'taxes/shiraberu/shinkoku/kisairei/2020/pdf/001.pdf', where: '給与 7,140,000円・医療費 500,000円・補てん 200,000円 → 医療費控除 200,000円・還付 15,552円（テストで再現）' },
  ];

  var V = {
    CHECKED: CHECKED,
    STALE_MONTHS: 12,             // 確認日からこの月数がたったら画面に注意を出す
    year: 2026,                   // 医療費を支払った年（lib/tax2026.js の年）
    label: '令和8年分',
    shinkoku: '令和9年（2027年）2〜3月',
    jumindo: '令和9年度',          // 医療費控除が効く住民税の年度
    SOURCES: SOURCES,

    // 通常の医療費控除（所得税法 73条、地方税法 314条の2第1項2号）
    iryohi: { floor: 100000, pct: 5, cap: 2000000 },
    // セルフメディケーション税制（措置法 41条の17、地方税法 附則4条の5）
    self: { floor: 12000, cap: 88000 },
    // 所得税の速算表（所得税法 89条・タックスアンサー No.2260）。[課税所得がこの額以下, 税率 %, 控除額]
    // 1,805 万円までは lib/tax2026.js の SOKUSAN と同じ値。4,000 万円超は最後の行
    sokusan: [
      [1950000, 5, 0],
      [3300000, 10, 97500],
      [6950000, 20, 427500],
      [9000000, 23, 636000],
      [18000000, 33, 1536000],
      [40000000, 40, 2796000],
      [Infinity, 45, 4796000],
    ],
    fukkou: 21,                   // 復興特別所得税 = 基準所得税額 × 21/1000（1円未満切り捨て）
    rates: [5, 10, 20, 23, 33, 40, 45],
    jumin: 10,                    // 住民税の所得割の標準税率（道府県民税 4% ＋ 市町村民税 6%）
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = V;
  else root.IryohiValues = V;
})(this);
